llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Golidocitinib, the closest analogue, shares the aminopyrimidine-indazole and methoxy/heteroaryl features and has human oral bioavailability >80%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "CC-292, a covalent inhibitor with an acrylamide and aminopyrimidine motif like the query, showed excellent oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Imatinib, an aminopyrimidine-aniline kinase inhibitor with a basic amine, has absolute oral bioavailability of 98.3% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Encorafenib, a heteroaryl pyrimidine kinase inhibitor, is rapidly and nearly completely absorbed with at least 86% bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zongertinib, a covalent EGFR inhibitor with acrylamide and pyrimidine features, was predicted to have 41% human oral bioavailability, above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Nilotinib, a related aminopyrimidine-aniline, showed absolute bioavailability of 17% at 400 mg in patients, providing contradictory low-F evidence, but its lower similarity and lack of the query's solubilizing basic side chain limit transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high oral bioavailability (F >= 20%) because the closest and most relevant analogues—golidocitinib, CC-292, imatinib, encorafenib, and zongertinib—show high or adequate human oral bioavailability, and the query's acrylamide/aminopyrimidine scaffold plus solubilizing basic amine aligns with these high-F compounds. Low-F nilotinib is less transferable due to lower similarity and structural differences.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "Morgan similarities to evidence molecules are modest (<0.35), limiting structural transferability.",
    "Nilotinib and flumatinib provide low-F data in a related chemotype, creating residual uncertainty.",
    "Zongertinib's 41% value is a prediction rather than a direct human measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

